cat > /home/mvhenten/development/.tmp/stallion-cf/store.mjs <<'EOF'
import { readFileSync, writeFileSync, chmodSync, mkdirSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { homedir } from "node:os";
import { join, dirname } from "node:path";

const src = process.argv[2];
const account = "f496802dcadb597e5939f6449c759a43";
const token = readFileSync(src, "utf8").trim();
const good = token.length > 0 && !token.includes("\n") && /^[A-Za-z0-9_-]+$/.test(token);
console.log(`${good ? "ok" : "bad format"} length=${token.length}`);
if (!good) process.exit(1);

const res = await fetch(`https://api.cloudflare.com/client/v4/accounts/${account}/workers/scripts`, {
  headers: { Authorization: `Bearer ${token}` },
});
console.log(`status=${res.status}`);
const body = await res.json().catch(() => ({}));
for (const e of body.errors ?? []) console.log(`error ${e.code}: ${e.message}`);

let attempt = 0;
for (;;) {
  const r = spawnSync("gh", ["secret", "set", "CLOUDFLARE_API_TOKEN", "--repo", "mvhenten/stallion"], { input: token, encoding: "utf8" });
  if (r.status === 0) { console.log("gh secret set ok"); break; }
  const err = (r.stderr ?? "").split(token).join("***");
  if (/rate limit/i.test(err) && attempt < 5) { attempt++; Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, 60000); continue; }
  console.log(`gh secret set failed: ${err.trim()}`);
  process.exit(1);
}

const envFile = join(homedir(), ".config/stallion/cf-env");
mkdirSync(dirname(envFile), { recursive: true });
writeFileSync(envFile, `CLOUDFLARE_API_TOKEN=${token}\nCLOUDFLARE_ACCOUNT_ID=${account}\n`, { mode: 0o600 });
chmodSync(envFile, 0o600);
console.log("cf-env written");
EOF
